const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');
require('dotenv').config();
const pool = require('./config/db');

const app = express();
const server = http.createServer(app);

// ফ্রন্টএন্ডের জন্য CORS ও সকেট কনফিগারেশন
app.use(cors({ origin: 'http://localhost:3000', methods: ['GET', 'POST', 'PATCH', 'DELETE'] }));
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: 'http://localhost:3000',
    methods: ['GET', 'POST'],
  },
});

// সকেট সংযোগ হ্যান্ডলার
io.on('connection', (socket) => {
  console.log(`⚡ Admin connected via Socket ID: ${socket.id}`);
});

// =================== লাইভ API এন্ডপয়েন্ট =================== //

// ১. সেটিংস লোড করা (Live DB)
app.get('/api/settings', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM settings WHERE id = 1');
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ২. সেটিংস আপডেট করা (Live DB)
app.post('/api/settings', async (req, res) => {
  const { bkash_number, nagad_number, support_number } = req.body;
  try {
    const result = await pool.query(
      `UPDATE settings SET bkash_number = $1, nagad_number = $2, support_number = $3 WHERE id = 1 RETURNING *`,
      [bkash_number, nagad_number, support_number]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৩. লাইভ রেস্টুরেন্ট লিস্ট ও মেনু পাওয়া
app.get('/api/restaurants', async (req, res) => {
  try {
    const restQuery = await pool.query('SELECT * FROM restaurants ORDER BY priority ASC, id DESC');
    const restaurants = restQuery.rows;

    for (let rest of restaurants) {
      const prodQuery = await pool.query(
        'SELECT * FROM products WHERE restaurant_id = $1 ORDER BY priority ASC',
        [rest.id]
      );
      rest.products = prodQuery.rows;
    }

    res.json(restaurants);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৪. নতুন রেস্টুরেন্ট তৈরি করা (Live DB)
app.post('/api/restaurants', async (req, res) => {
  const { name, phone, password, orderType, priority } = req.body;
  try {
    const result = await pool.query(
      `INSERT INTO restaurants (name, phone, password, order_type, priority)
       VALUES ($1, $2, $3, $4, $5) RETURNING *`,
      [name, phone, password, orderType || 'both', priority || 1]
    );
    res.status(201).json({ ...result.rows[0], products: [] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৫. রেস্টুরেন্ট ওপেন/ক্লোজ টগল
app.patch('/api/restaurants/:id/toggle', async (req, res) => {
  try {
    const result = await pool.query(
      `UPDATE restaurants SET is_open = NOT is_open WHERE id = $1 RETURNING *`,
      [req.params.id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৬. রেস্টুরেন্টের প্রায়োরিটি আপডেট
app.patch('/api/restaurants/:id/priority', async (req, res) => {
  const { priority } = req.body;
  try {
    const result = await pool.query(
      'UPDATE restaurants SET priority = $1 WHERE id = $2 RETURNING *',
      [priority, req.params.id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৭. রেস্টুরেন্ট পাসওয়ার্ড আপডেট
app.patch('/api/restaurants/:id/password', async (req, res) => {
  const { password } = req.body;
  try {
    const result = await pool.query(
      'UPDATE restaurants SET password = $1 WHERE id = $2 RETURNING *',
      [password, req.params.id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৮. রেস্টুরেন্টে মেনু প্রোডাক্ট যুক্ত করা
app.post('/api/products', async (req, res) => {
  const { restaurant_id, name, price, priority } = req.body;
  try {
    const result = await pool.query(
      `INSERT INTO products (restaurant_id, name, price, priority)
       VALUES ($1, $2, $3, $4) RETURNING *`,
      [restaurant_id, name, price, priority || 1]
    );
    res.status(201).json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ৯. মেনু প্রোডাক্ট স্টক অন/অফ টগল
app.patch('/api/products/:id/toggle-stock', async (req, res) => {
  try {
    const result = await pool.query(
      `UPDATE products SET in_stock = NOT in_stock WHERE id = $1 RETURNING *`,
      [req.params.id]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ১০. মেনু প্রোডাক্ট ডিলিট করা
app.delete('/api/products/:id', async (req, res) => {
  try {
    await pool.query('DELETE FROM products WHERE id = $1', [req.params.id]);
    res.json({ success: true, message: 'Product deleted' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ১১. সমস্ত অর্ডার পাওয়ার এন্ডপয়েন্ট (Live DB)
app.get('/api/orders', async (req, res) => {
  try {
    const result = await pool.query(`
      SELECT
        o.*,
        r.name AS restaurant_name,
        rd.name AS rider_name,
        rd.phone AS rider_phone
      FROM orders o
      LEFT JOIN restaurants r ON o.restaurant_id = r.id
      LEFT JOIN riders rd ON o.rider_id = rd.id
      ORDER BY o.id DESC
    `);
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ১২. লাইভ ড্যাশবোর্ড স্ট্যাটস ও মেট্রিক্স API
app.get('/api/dashboard/stats', async (req, res) => {
  const { filter } = req.query;

  let dateCondition = "created_at >= CURRENT_DATE";
  if (filter === 'weekly') {
    dateCondition = "created_at >= NOW() - INTERVAL '7 days'";
  } else if (filter === 'monthly') {
    dateCondition = "created_at >= NOW() - INTERVAL '30 days'";
  }

  try {
    const salesQuery = await pool.query(`
      SELECT
        COALESCE(SUM(total_amount), 0) AS total_sales,
        COUNT(id) AS total_orders,
        COUNT(CASE WHEN status NOT IN ('delivered', 'cancelled') THEN 1 END) AS active_orders
      FROM orders
      WHERE ${dateCondition}
    `);

    const paymentQuery = await pool.query(`
      SELECT
        payment_method,
        COALESCE(SUM(total_amount), 0) AS amount
      FROM orders
      WHERE ${dateCondition}
      GROUP BY payment_method
    `);

    const riderQuery = await pool.query(`
      SELECT
        COUNT(id) AS total_riders,
        COUNT(CASE WHEN status = 'active' THEN 1 END) AS online_riders
      FROM riders
    `);

    const recentActivity = await pool.query(`
      SELECT
        id,
        customer_name,
        total_amount,
        status,
        TO_CHAR(created_at, 'HH12:MI AM') AS time
      FROM orders
      ORDER BY id DESC
      LIMIT 5
    `);

    const stats = salesQuery.rows[0];
    const totalSalesNum = Number(stats.total_sales);
    const platformCommission = (totalSalesNum * 0.10).toFixed(2);

    const payments = { cod: 0, bkash: 0, nagad: 0 };
    paymentQuery.rows.forEach(p => {
      const method = (p.payment_method || '').toLowerCase();
      if (method.includes('cod') || method.includes('cash')) payments.cod = Number(p.amount);
      else if (method.includes('bkash')) payments.bkash = Number(p.amount);
      else if (method.includes('nagad')) payments.nagad = Number(p.amount);
    });

    res.json({
      totalSales: totalSalesNum,
      activeOrders: Number(stats.active_orders),
      totalOrders: Number(stats.total_orders),
      commission: Number(platformCommission),
      onlineRiders: `${riderQuery.rows[0]?.online_riders || 0} / ${riderQuery.rows[0]?.total_riders || 0}`,
      payments,
      recentActivity: recentActivity.rows
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ১৩. লাইভ অর্ডার তৈরি (সকেট ইভেন্ট পাঠানো সহ)
app.post('/api/orders', async (req, res) => {
  const { customer_name, customer_phone, address, restaurant_id, total_amount, payment_method } = req.body;
  try {
    const result = await pool.query(
      `INSERT INTO orders (customer_name, customer_phone, address, restaurant_id, total_amount, payment_method)
       VALUES ($1, $2, $3, $4, $5, $6) RETURNING *`,
      [customer_name, customer_phone, address, restaurant_id || null, total_amount, payment_method || 'COD']
    );

    const newOrder = result.rows[0];

    io.emit('new_order', {
      id: newOrder.id,
      customer_name: newOrder.customer_name,
      customer_phone: newOrder.customer_phone,
      address: newOrder.address,
      restaurant_name: 'Live Partner',
      total_amount: Number(newOrder.total_amount),
      payment_method: newOrder.payment_method,
      payment_status: newOrder.payment_status,
      status: newOrder.status,
      items: []
    });

    res.status(201).json(newOrder);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ১৪. অর্ডার স্ট্যাটাস পরিবর্তন
app.patch('/api/orders/:id/status', async (req, res) => {
  const { status } = req.body;
  const orderId = String(req.params.id).replace('ORD-', '');
  try {
    const result = await pool.query(
      'UPDATE orders SET status = $1 WHERE id = $2 RETURNING *',
      [status, orderId]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`🚀 Live Backend & Socket Server running on port ${PORT}`);
});
